        instr_type_wb_o    = WB_INSTR_LOAD;
        lsu_req_o          = lsu_req_actual;
        lsu_we_o           = 1'b0;
        lsu_type_o         = 2'b10;
        lsu_sign_ext_o     = 1'b1;
        expecting_load_resp_o = 1'b1;
      end
      311: begin  // lw s4,44(sp) (PC=0x55c)
        alu_operand_a_ex_o = rf_rdata_a;
        alu_operand_b_ex_o = 32'h0000002C;
        rf_raddr_a_o       = 5'd2;
        rf_ren_a_o         = 1'b1;
        rf_waddr_id_o      = 5'd20;
        rf_we_id_o         = 1'b0;
        en_wb_o            = 1'b1;
        instr_type_wb_o    = WB_INSTR_LOAD;
        lsu_req_o          = lsu_req_actual;
        lsu_we_o           = 1'b0;
        lsu_type_o         = 2'b10;
        lsu_sign_ext_o     = 1'b1;
        expecting_load_resp_o = 1'b1;
      end
      312: begin  // addi sp,sp,64 (PC=0x560)
        alu_operand_a_ex_o = rf_rdata_a;
        alu_operand_b_ex_o = 32'h00000040;
        rf_raddr_a_o       = 5'd2;
        rf_ren_a_o         = 1'b1;
        rf_waddr_id_o      = 5'd2;
        rf_we_id_o         = 1'b1;
        rf_wdata_id_o      = result_ex_i;
        en_wb_o            = 1'b1;
        instr_type_wb_o    = WB_INSTR_OTHER;
      end
      313: begin  // ret (PC=0x564)
        rf_raddr_a_o = 5'd1;   // ra
        rf_ren_a_o   = 1'b1;
        rf_we_id_o   = 1'b0;
        en_wb_o      = 1'b0;
        state_d = rf_rdata_a[8:0];
      end
      default: state_d = '0;
    endcase
  end

  assign ctrl_busy_o             = (state_q != 313);
  assign illegal_insn_o          = 1'b0;
  assign instr_first_cycle_id_o  = first_cycle;
  assign instr_valid_clear_o     = 1'b0;
  assign id_in_ready_o           = 1'b1;
